/**
 * errors.mjs — the python-jose exception hierarchy, ported to ES classes.
 *
 * python-jose (jose/exceptions.py) defines a small tree of exceptions:
 *
 *   JOSEError
 *   ├── JWSError
 *   │   ├── JWSSignatureError
 *   │   └── JWSAlgorithmError
 *   ├── JWTError
 *   │   ├── JWTClaimsError
 *   │   └── ExpiredSignatureError
 *   └── JWKError
 *
 * Python exceptions carry no default message (str(JWSError()) == ''), but a
 * handful of raise sites in python-jose always use the same wording. Those
 * strings are exposed here as the static `DEFAULT_MESSAGE` of the matching
 * class, so `new JWSSignatureError()` reads like the library's own raise.
 *
 * This module has no imports of any kind — by design it is pure, dependency
 * free, and safe to load from anywhere in the port.
 */

/**
 * Resolve the message passed to a constructor into the string that `super()`
 * receives.
 *
 * - `undefined` / `null` (i.e. "no message given") -> the class default,
 *   mirroring Python's `raise JWSError` with no arguments.
 * - an Error instance -> its message, mirroring python-jose's habit of
 *   re-raising a caught exception as `raise JWSError(e)`, where `str(e)` is
 *   what the user ends up seeing.
 * - anything else -> coerced with String(), like Python's str().
 *
 * @param {unknown} message value handed to the constructor
 * @param {Function} target the concrete class being constructed (new.target)
 * @returns {string} message for the underlying Error
 */
function normalizeMessage(message, target) {
  if (message === undefined || message === null) {
    const fallback = target && target.DEFAULT_MESSAGE;
    return typeof fallback === 'string' ? fallback : '';
  }
  if (message instanceof Error) {
    return String(message.message);
  }
  return String(message);
}

/**
 * Base class for every error raised by this library.
 * Equivalent to jose.exceptions.JOSEError.
 */
export class JOSEError extends Error {
  /** python-jose has no default text for the base class. */
  static DEFAULT_MESSAGE = '';

  /**
   * @param {unknown} [message] optional message (or a wrapped Error)
   */
  constructor(message) {
    super(normalizeMessage(message, new.target));
    this.name = 'JOSEError';
    // Keep the constructor frames out of the stack when V8 lets us.
    if (typeof Error.captureStackTrace === 'function') {
      Error.captureStackTrace(this, new.target);
    }
  }
}

/**
 * Something went wrong while signing or verifying a JWS.
 * Equivalent to jose.exceptions.JWSError.
 */
export class JWSError extends JOSEError {
  /**
   * @param {unknown} [message] optional message (or a wrapped Error)
   */
  constructor(message) {
    super(message);
    this.name = 'JWSError';
  }
}

/**
 * The signature did not match the signing input for any candidate key.
 * Equivalent to jose.exceptions.JWSSignatureError.
 */
export class JWSSignatureError extends JWSError {
  /** jws._verify_signature: raise JWSSignatureError("Signature verification failed.") */
  static DEFAULT_MESSAGE = 'Signature verification failed.';

  /**
   * @param {unknown} [message] optional message (or a wrapped Error)
   */
  constructor(message) {
    super(message);
    this.name = 'JWSSignatureError';
  }
}

/**
 * The requested / advertised algorithm is not implemented.
 * Equivalent to jose.exceptions.JWSAlgorithmError.
 */
export class JWSAlgorithmError extends JWSError {
  /** jws: raise JWSAlgorithmError("Algorithm not supported.") */
  static DEFAULT_MESSAGE = 'Algorithm not supported.';

  /**
   * @param {unknown} [message] optional message (or a wrapped Error)
   */
  constructor(message) {
    super(message);
    this.name = 'JWSAlgorithmError';
  }
}

/**
 * Something went wrong while encoding or decoding a JWT.
 * Equivalent to jose.exceptions.JWTError.
 */
export class JWTError extends JOSEError {
  /**
   * @param {unknown} [message] optional message (or a wrapped Error)
   */
  constructor(message) {
    super(message);
    this.name = 'JWTError';
  }
}

/**
 * A registered claim failed validation (iat, aud, iss, sub, jti, at_hash, ...).
 * Equivalent to jose.exceptions.JWTClaimsError.
 */
export class JWTClaimsError extends JWTError {
  /**
   * @param {unknown} [message] optional message (or a wrapped Error)
   */
  constructor(message) {
    super(message);
    this.name = 'JWTClaimsError';
  }
}

/**
 * The `exp` claim is in the past (outside the allowed leeway).
 * Equivalent to jose.exceptions.ExpiredSignatureError.
 */
export class ExpiredSignatureError extends JWTError {
  /** jwt._validate_exp: raise ExpiredSignatureError("Signature has expired.") */
  static DEFAULT_MESSAGE = 'Signature has expired.';

  /**
   * @param {unknown} [message] optional message (or a wrapped Error)
   */
  constructor(message) {
    super(message);
    this.name = 'ExpiredSignatureError';
  }
}

/**
 * A key could not be constructed or used.
 * Equivalent to jose.exceptions.JWKError — included for hierarchy fidelity;
 * the HS256-only port raises it only when a key is unusable.
 */
export class JWKError extends JOSEError {
  /**
   * @param {unknown} [message] optional message (or a wrapped Error)
   */
  constructor(message) {
    super(message);
    this.name = 'JWKError';
  }
}

// scratch checks for /output/lib/errors.mjs
import {
  JOSEError,
  JWSError,
  JWSSignatureError,
  JWSAlgorithmError,
  JWTError,
  JWTClaimsError,
  ExpiredSignatureError,
  JWKError,
} from '/output/lib/errors.mjs';

let failures = 0;
function check(label, actual, expected) {
  const ok = actual === expected;
  if (!ok) failures++;
  console.log(`${ok ? 'ok  ' : 'FAIL'} ${label} -> ${JSON.stringify(actual)}${ok ? '' : ` (want ${JSON.stringify(expected)})`}`);
}

// names
check('JOSEError.name', new JOSEError().name, 'JOSEError');
check('JWSError.name', new JWSError().name, 'JWSError');
check('JWSSignatureError.name', new JWSSignatureError().name, 'JWSSignatureError');
check('JWSAlgorithmError.name', new JWSAlgorithmError().name, 'JWSAlgorithmError');
check('JWTError.name', new JWTError().name, 'JWTError');
check('JWTClaimsError.name', new JWTClaimsError().name, 'JWTClaimsError');
check('ExpiredSignatureError.name', new ExpiredSignatureError().name, 'ExpiredSignatureError');
check('JWKError.name', new JWKError().name, 'JWKError');

// inheritance
check('JWSError isa JOSEError', new JWSError() instanceof JOSEError, true);
check('JWSSignatureError isa JWSError', new JWSSignatureError() instanceof JWSError, true);
check('JWSAlgorithmError isa JWSError', new JWSAlgorithmError() instanceof JWSError, true);
check('JWTClaimsError isa JWTError', new JWTClaimsError() instanceof JWTError, true);
check('ExpiredSignatureError isa JWTError', new ExpiredSignatureError() instanceof JWTError, true);
check('JWTError isa JOSEError', new JWTError() instanceof JOSEError, true);
check('JWKError isa JOSEError', new JWKError() instanceof JOSEError, true);
check('all isa Error', new JWTClaimsError() instanceof Error, true);
check('JWTError not isa JWSError', new JWTError() instanceof JWSError, false);

// default + explicit messages
check('JOSEError default msg', new JOSEError().message, '');
check('JWSError default msg', new JWSError().message, '');
check('JWSSignatureError default msg', new JWSSignatureError().message, 'Signature verification failed.');
check('JWSAlgorithmError default msg', new JWSAlgorithmError().message, 'Algorithm not supported.');
check('ExpiredSignatureError default msg', new ExpiredSignatureError().message, 'Signature has expired.');
check('JWTClaimsError explicit', new JWTClaimsError('Issued At claim (iat) must be an integer.').message,
  'Issued At claim (iat) must be an integer.');
check('override default', new JWSAlgorithmError('The specified alg value is not allowed').message,
  'The specified alg value is not allowed');
check('empty string kept', new JWSSignatureError('').message, '');
check('wrapped Error unwrapped', new JWSError(new TypeError('boom')).message, 'boom');
check('non-string coerced', new JWSError(42).message, '42');
check('static default lookup', JWSSignatureError.DEFAULT_MESSAGE, 'Signature verification failed.');

// throw/catch + toString behaviour
try {
  throw new JWSSignatureError();
} catch (e) {
  check('caught as JOSEError', e instanceof JOSEError, true);
  check('toString', String(e), 'JWSSignatureError: Signature verification failed.');
  check('has stack', typeof e.stack === 'string' && e.stack.length > 0, true);
  check('stack starts with name', e.stack.startsWith('JWSSignatureError: Signature verification failed.'), true);
}

console.log(failures === 0 ? '\nALL PASS' : `\n${failures} FAILURE(S)`);
process.exit(failures === 0 ? 0 : 1);
